const contacts = $input.all();
const results = [];

for (const item of contacts) {
  const contact = item.json;
  const daysInactive = contact.days_inactive || 30;

  let template, subject, urgency;

  if (daysInactive > 90) {
    // Very cold - last chance
    template = 'd-reengagement-final';
    subject = `${contact.first_name || 'Hi'}, we miss you! Here's something special`;
    urgency = 'high';
  } else if (daysInactive > 60) {
    // Cold - incentive offer
    template = 'd-reengagement-incentive';
    subject = `${contact.first_name || 'Hi'}, exclusive offer just for you`;
    urgency = 'medium';
  } else {
    // Warm - gentle reminder
    template = 'd-reengagement-gentle';
    subject = `${contact.first_name || 'Hi'}, here's what you've been missing`;
    urgency = 'low';
  }

  results.push({
    json: {
      ...contact,
      template_id: template,
      email_subject: subject,
      urgency: urgency,
      days_inactive: daysInactive
    }
  });
}

return results;
